import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"NVMe-Over-Fabrics Support for Ceph | Ceph Days NYC 2024","description":"","frontmatter":{"title":"NVMe-Over-Fabrics Support for Ceph | Ceph Days NYC 2024","date":"2024-05-24T00:00:00.000Z","updated":"2024-05-24T00:00:00.000Z","tags":["Ceph","NVMe","oF","Storage Performance","Distributed Storage","Cloud Computing"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/NVMe-Over-Fabrics_Support_for_Ceph_Ceph_Days_NYC_2024.md","filePath":"posts/2024/NVMe-Over-Fabrics_Support_for_Ceph_Ceph_Days_NYC_2024.md","lastUpdated":1780459816000}'),t={name:"posts/2024/NVMe-Over-Fabrics_Support_for_Ceph_Ceph_Days_NYC_2024.md"};function o(s,e,p,n,u,h){return l(),r("div",null,[...e[0]||(e[0]=[i('<p>categories:</p><ul><li>&quot;视频总结&quot; subtitle: NVMe-Over-Fabrics_Support_for_Ceph_Ceph_Days_NYC_2024</li></ul><p>会议纪要</p><h3 id="会议主题-nvme-over-tcp-和-nvme-of-gateway-的集成与性能优化" tabindex="-1">会议主题：NVMe over TCP 和 NVMe-oF Gateway 的集成与性能优化 <a class="header-anchor" href="#会议主题-nvme-over-tcp-和-nvme-of-gateway-的集成与性能优化" aria-label="Permalink to &quot;会议主题：NVMe over TCP 和 NVMe-oF Gateway 的集成与性能优化&quot;">​</a></h3><h3 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h3><h3 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h3><h3 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h3><ul><li><strong>Mike Burkhart</strong> - IBM 产品经理，负责 NVMe over TCP 和 VMware 集成</li></ul><h3 id="会议内容概要" tabindex="-1">会议内容概要： <a class="header-anchor" href="#会议内容概要" aria-label="Permalink to &quot;会议内容概要：&quot;">​</a></h3><ol><li><p><strong>NVMe 驱动介绍</strong></p><ul><li>NVMe 驱动具有高耐用性、并行处理能力和高度可扩展性。</li><li>NVM fabric 规范自2018-2019年成熟，支持通过不同传输介质（如光纤通道、RDMA 和 NVMe over TCP）访问 NVMe 磁盘。</li></ul></li><li><p><strong>NVMe over TCP 的优势</strong></p><ul><li>通过网络传输实现 NVMe 驱动的高容量、可扩展性和耐用性。</li><li>利用 SEF（Scalable Ethernet Fabric）的扩展能力，增强 NVMe 的耐用性和并行处理能力。</li></ul></li><li><p><strong>TCP 连接模型</strong></p><ul><li>每个 TCP 连接实例使用用户空间驱动，每个连接对应一个独立的会话和 NVMe 命名空间控制器。</li><li>这种一对一的连接模型支持高度的可扩展性和控制灵活性。</li></ul></li><li><p><strong>性能优化与传统技术对比</strong></p><ul><li>与传统的 iSCSI 技术相比，NVMe over TCP 提供了更高的吞吐量、更好的 IOPS 和更低的延迟。</li><li>RBD（RADOS Block Device）作为底层实现，已经过充分测试和验证。</li></ul></li><li><p><strong>架构与集成</strong></p><ul><li>NVMe-oF Gateway 采用用户空间驱动，基于 SPDK（Storage Performance Development Kit）开发。</li><li>支持多路径和负载均衡，每个 Gateway 可以加载所有可用的子系统，实现环境隔离。</li></ul></li><li><p><strong>控制器与子系统管理</strong></p><ul><li>控制器是临时性的，客户端断开连接后，控制器可以被回收利用。</li><li>子系统用于协调命名空间，支持多子系统和多 Gateway 的扩展。</li></ul></li><li><p><strong>配置与安全性</strong></p><ul><li>Gateway 的配置存储在 omap 中，支持配置在实例间的迁移。</li><li>使用 SPDK 和 TLS PSK 实现加密通信，未来计划支持 inband o。</li></ul></li><li><p><strong>性能测试结果</strong></p><ul><li>与 iSCSI 相比，NVMe over TCP 在多个性能指标上显示出显著优势，特别是在多节点和多反应器配置下。</li></ul></li><li><p><strong>VMware 集成</strong></p><ul><li>支持通过 VMware vSphere APIs for Storage Awareness (VASA) 进行存储加速和卸载。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h3><ul><li>确认 NVMe over TCP 作为下一代存储解决方案的技术优势和性能表现。</li><li>继续推进与 VMware 的集成工作，优化存储性能和效率。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>完成 NVMe over TCP 与现有 RBD 接口的完全映射。</li><li>继续进行性能测试和优化，确保在不同工作负载下的稳定性和高效性。</li><li>推进与 VMware 的深度集成，实现更高效的存储管理和优化。</li></ul><h3 id="会议结束时间-具体时间" tabindex="-1">会议结束时间：[具体时间] <a class="header-anchor" href="#会议结束时间-具体时间" aria-label="Permalink to &quot;会议结束时间：[具体时间]&quot;">​</a></h3>',15)])])}const d=a(t,[["render",o]]);export{c as __pageData,d as default};
